package com.haucheng.erp.mapper;
import com.haucheng.erp.entity.MdProduct; import com.haucheng.erp.vo.ProductView; import com.haucheng.erp.common.Pagination; import org.apache.ibatis.annotations.*; import java.util.List;
@Mapper public interface ProductMapper {
 @Select("SELECT p.*,c.category_name,b.brand_name,u.unit_name FROM md_products p JOIN md_categories c ON c.id=p.category_id JOIN md_brands b ON b.id=p.brand_id JOIN md_units u ON u.id=p.unit_id WHERE p.id=#{id}") ProductView selectViewById(@Param("id") Long id);
 @Select("SELECT * FROM md_products WHERE id=#{id}") MdProduct selectById(@Param("id") Long id);
 @Select("SELECT * FROM md_products WHERE id=#{id} FOR UPDATE") MdProduct selectByIdForUpdate(@Param("id") Long id);
 @Select("<script>SELECT p.*,c.category_name,b.brand_name,u.unit_name FROM md_products p JOIN md_categories c ON c.id=p.category_id JOIN md_brands b ON b.id=p.brand_id JOIN md_units u ON u.id=p.unit_id <where><if test='code!=null and code!=\"\"'> AND p.product_code LIKE CONCAT('%',#{code},'%')</if><if test='name!=null and name!=\"\"'> AND p.product_name LIKE CONCAT('%',#{name},'%')</if><if test='categoryId!=null'> AND p.category_id=#{categoryId}</if><if test='brandId!=null'> AND p.brand_id=#{brandId}</if><if test='model!=null and model!=\"\"'> AND p.model LIKE CONCAT('%',#{model},'%')</if><if test='status!=null'> AND p.status=#{status}</if><if test='productType!=null and productType!=\"\"'> AND p.product_type=#{productType}</if></where> ORDER BY p.id DESC LIMIT #{pagination.size} OFFSET #{pagination.offset}</script>") List<ProductView> selectPage(@Param("code") String code,@Param("name") String name,@Param("categoryId") Long categoryId,@Param("brandId") Long brandId,@Param("model") String model,@Param("status") Boolean status,@Param("productType") String productType,@Param("pagination") Pagination pagination);
 @Select("<script>SELECT COUNT(*) FROM md_products p <where><if test='code!=null and code!=\"\"'> AND p.product_code LIKE CONCAT('%',#{code},'%')</if><if test='name!=null and name!=\"\"'> AND p.product_name LIKE CONCAT('%',#{name},'%')</if><if test='categoryId!=null'> AND p.category_id=#{categoryId}</if><if test='brandId!=null'> AND p.brand_id=#{brandId}</if><if test='model!=null and model!=\"\"'> AND p.model LIKE CONCAT('%',#{model},'%')</if><if test='status!=null'> AND p.status=#{status}</if><if test='productType!=null and productType!=\"\"'> AND p.product_type=#{productType}</if></where></script>") long count(@Param("code") String code,@Param("name") String name,@Param("categoryId") Long categoryId,@Param("brandId") Long brandId,@Param("model") String model,@Param("status") Boolean status,@Param("productType") String productType);
 @Select("SELECT COUNT(*) FROM md_products WHERE product_code=#{code} AND (#{excludeId} IS NULL OR id!=#{excludeId})") int countByCode(@Param("code") String code,@Param("excludeId") Long excludeId);
 @Insert("INSERT INTO md_products(product_code,product_name,category_id,brand_id,model,specification,unit_id,product_type,track_sn,track_mac,is_fixed_asset,enable_qrcode,safety_stock,min_stock,max_stock,remark,status) VALUES(#{productCode},#{productName},#{categoryId},#{brandId},#{model},#{specification},#{unitId},#{productType},#{trackSn},#{trackMac},#{isFixedAsset},#{enableQrcode},#{safetyStock},#{minStock},#{maxStock},#{remark},#{status})") @Options(useGeneratedKeys=true,keyProperty="id") int insert(MdProduct e);
 @Update("UPDATE md_products SET product_code=#{productCode},product_name=#{productName},category_id=#{categoryId},brand_id=#{brandId},model=#{model},specification=#{specification},unit_id=#{unitId},product_type=#{productType},track_sn=#{trackSn},track_mac=#{trackMac},is_fixed_asset=#{isFixedAsset},enable_qrcode=#{enableQrcode},safety_stock=#{safetyStock},min_stock=#{minStock},max_stock=#{maxStock},remark=#{remark},status=#{status} WHERE id=#{id}") int update(MdProduct e);
 @Update("UPDATE md_products SET status=#{status} WHERE id=#{id}") int updateStatus(@Param("id") Long id,@Param("status") Boolean status);
}
